// ---------------------------------------------------------------------------
// La escena del pase de salida, armada a mano: una pelota naranja sobre un
// fondo, con la mitad izquierda al sol y la mitad derecha a la sombra.
// Cada pixel son TRES numeros, no uno. Eso es todo lo que cambia con el color.
// ---------------------------------------------------------------------------
const N = 20;
const SOMBRA = 0.45;                 // la sombra baja la luz, no cambia el color
const NARANJA = [230, 120, 30];
const FONDO   = [60, 70, 85];

const img = [];                       // img[y][x] = [R, G, B]
for (let y = 0; y < N; y++) {
  const fila = [];
  for (let x = 0; x < N; x++) {
    const dx = x - 9.5, dy = y - 9.5;
    const dentro = (dx * dx + dy * dy) <= 42;          // la pelota
    let px = dentro ? NARANJA.slice() : FONDO.slice();
    if (x >= N / 2) px = px.map(v => Math.round(v * SOMBRA));   // la sombra
    fila.push(px);
  }
  img.push(fila);
}

// ---------------------------------------------------------------------------
// RGB -> HSV. H en grados (0-360), S y V entre 0 y 1.
// ---------------------------------------------------------------------------
function aHSV(r, g, b) {
  r /= 255; g /= 255; b /= 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b), d = max - min;
  let h = 0;
  if (d !== 0) {
    if (max === r)      h = 60 * (((g - b) / d) % 6);
    else if (max === g) h = 60 * (((b - r) / d) + 2);
    else                h = 60 * (((r - g) / d) + 4);
  }
  if (h < 0) h += 360;
  return { h: h, s: max === 0 ? 0 : d / max, v: max };
}

// Un pixel de la pelota al sol y otro a la sombra, para comparar.
const alSol    = img[9][6];
const aLaSombra = img[9][13];
const hsvSol    = aHSV(alSol[0], alSol[1], alSol[2]);
const hsvSombra = aHSV(aLaSombra[0], aLaSombra[1], aLaSombra[2]);

const salida = [];

// --- 1. La imagen, y que es un canal --------------------------------------
const ESCALA = ' .:-=+*#%@';
function dibujarCanal(c) {
  return img.map(f => f.map(px => {
    const i = Math.round((px[c] / 255) * (ESCALA.length - 1));
    return ESCALA[i] + ESCALA[i];
  }).join('')).join('\n');
}

salida.push({
  paso: '1. Una imagen en color son TRES matrices',
  tamanio: N + ' x ' + N + ' x 3 = ' + (N * N * 3) + ' numeros',
  canal_R: dibujarCanal(0),
  canal_G: dibujarCanal(1),
  canal_B: dibujarCanal(2),
  ojo: 'El canal rojo no se ve rojo: es un mapa de cuanto rojo hay en cada lugar.',
});

// --- 2. La trampa de OpenCV ------------------------------------------------
salida.push({
  paso: '2. La trampa del BGR',
  el_pixel_bien_leido_RGB: 'R=' + alSol[0] + ' G=' + alSol[1] + ' B=' + alSol[2] + '  -> naranja',
  el_mismo_leido_como_BGR: 'R=' + alSol[2] + ' G=' + alSol[1] + ' B=' + alSol[0] + '  -> celeste',
  por_eso: 'Los mismos tres numeros, en otro orden, son otro color. OpenCV lee BGR y Pillow RGB.',
});

// --- 3. Grises: promedio simple contra ponderado ---------------------------
const grisSimple = Math.round((alSol[0] + alSol[1] + alSol[2]) / 3);
const grisPond = Math.round(0.299 * alSol[0] + 0.587 * alSol[1] + 0.114 * alSol[2]);
salida.push({
  paso: '3. Pasar a grises no es promediar',
  promedio_simple: '(230 + 120 + 30) / 3 = ' + grisSimple,
  formula_ponderada: '0.299*R + 0.587*G + 0.114*B = ' + grisPond,
  diferencia: Math.abs(grisPond - grisSimple) + ' niveles sobre 255',
  por_que: 'El ojo es mucho mas sensible al verde que al azul. El promedio simple no lo respeta.',
});

// --- 4. El remate: RGB contra HSV -----------------------------------------
function pct(x) { return (x * 100).toFixed(1) + ' %'; }
const difRGB = Math.round(
  (Math.abs(alSol[0] - aLaSombra[0]) + Math.abs(alSol[1] - aLaSombra[1]) +
   Math.abs(alSol[2] - aLaSombra[2])) / 3);

salida.push({
  paso: '4. La misma pelota, al sol y a la sombra',
  en_RGB_al_sol:      'R=' + alSol[0] + ' G=' + alSol[1] + ' B=' + alSol[2],
  en_RGB_a_la_sombra: 'R=' + aLaSombra[0] + ' G=' + aLaSombra[1] + ' B=' + aLaSombra[2],
  en_RGB_cambian:     'los TRES canales, ' + difRGB + ' niveles en promedio',
  en_HSV_al_sol:      'H=' + hsvSol.h.toFixed(1) + ' grados   S=' + pct(hsvSol.s) + '   V=' + pct(hsvSol.v),
  en_HSV_a_la_sombra: 'H=' + hsvSombra.h.toFixed(1) + ' grados   S=' + pct(hsvSombra.s) + '   V=' + pct(hsvSombra.v),
  el_tono_se_movio:   Math.abs(hsvSol.h - hsvSombra.h).toFixed(2) + ' grados',
  conclusion: 'En RGB el sol y la sombra son dos colores distintos. En HSV es el MISMO tono ' +
              'con menos luz. Por eso un filtro por color se hace en HSV.',
});

return salida.map(json => ({ json }));
